  insert into public.questions (stage, question_type, stem, model_answer, explanation, key_points, subject_id, topic_id, paper_id, difficulty, marks,
                                estimated_seconds, origin, status, parent_question_id, variation_type, ai_review, passage_group, passage_position, verified_by, subject_group_id, specialisation_id, image_url)
  values ('ME', 'long_answer', 'Although our Constitution provides a legal framework to foster the growth and sustainability of the extended family and community life, there is mounting evidence that traditional family structures and community practices are fast changing and declining.
Discuss how, in your opinion, the family, community and societal relationships that form the very core of Bhutanese society are changing today, and suggest ways to promote community vitality and the integrity of the extended family system. (20 marks)', 'The Constitution (Article 9) directs the State to foster conditions for the strengthening of the extended family and a cohesive society, and community vitality is one of the nine domains of GNH. Yet these foundations are changing.
How relationships are changing:
1. Extended to nuclear families: young people move to towns or abroad for work and education, forming small nuclear households; grandparents often stay in villages alone, and some houses are left empty (gungtong).
2. Weakening intergenerational bonds: fewer shared meals and less time together; values such as respect for elders, gratitude to parents (ley jumdrey) and family duty are not always passed on.
3. Community support declining: villagers once shared labour in planting, harvesting and house building and helped each other at births, deaths and rituals; now labour is hired for cash and services are expected from the government.
4. Individualism and consumerism: busy urban lives, competition and material aspirations reduce time for community; neighbours in towns often do not know each other.
5. Technology: social media connects people far away but can reduce face-to-face interaction within families.
6. Family breakdown: rising divorce, single-parent families and domestic problems affect children.
Ways to strengthen community vitality and the extended family:
1. Family-friendly policies - flexible work, child care, support for families who care for elderly parents, and housing that allows multi-generational living.
2. Value education in schools and homes on family, respect and community service.
3. Local governments, schools and civil society to organise community events, festivals, clean-ups and volunteer work; promote Desuung and youth volunteerism.
4. Community spaces and neighbourhood associations in towns.
5. Balanced regional development and rural jobs to reduce migration.
6. Use technology to keep families connected across distances.
7. Personally, spend time with family and elders, take part in community activities and help neighbours.', null, '[{"point": "Constitutional basis: Article 9 (State shall endeavour to foster conditions for strengthening extended family and cohesive society), GNH community vitality domain", "marks": 3}, {"point": "Changes: extended to nuclear families, rural-urban and overseas migration, elderly left alone (gungtong), weakening respect/ ley jumdrey, monetised labour instead of mutual help, individualism and consumerism, social media, divorce and broken families, less participation in community rituals and festivals", "marks": 9}, {"point": "Ways: family-friendly policies, elderly care support and intergenerational living, value education, community activities and volunteerism, local governments and CSOs, community centres in towns, rural development to reduce migration, use technology to connect families, personal role", "marks": 8}]'::jsonb, (select id from public.subjects where slug = 'bhutan-institutions-development'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'bhutan-institutions-development') and t.slug = 'society-and-community-vitality'), (select id from public.exam_papers where code = 'me-general-3'), 'standard', 20,
    2160, 'historical_official', 'awaiting_review',
